#!/usr/bin/env python3
"""Checker (ros2-demos): launch actions, entry points, component registrations, and where they lead.

Run only as: python3 -I check_ros2-demos_launch.py SRC BUILD GIT_LIST_Z DB_JSON COMM_JSON INC_DETAIL_JSON OUT_JSON
Nothing in SRC is executed or imported: launch .py and setup.py are read with ast, XML/YAML with regexes.
Executable -> source mapping is derived from the configure outputs only:
  * BUILD/<pkg>/rclcpp_components/node_main_<exe>.cpp (generated by rclcpp_components_register_node at configure)
    names the component class -> the workspace file containing RCLCPP_COMPONENTS_REGISTER_NODE(<class>);
  * otherwise the compile database 'output' paths CMakeFiles/<exe>.dir/... give the target's own sources;
  * ament_python: setup.py entry_points console_scripts 'exe = module:func' -> module file.
"""
import ast
import collections
import json
import os
import re
import sys

NODE_CALLS = {'Node', 'LifecycleNode', 'ComposableNode', 'ComposableNodeContainer', 'ExecuteProcess', 'IncludeLaunchDescription'}


def const(n):
    return n.value if isinstance(n, ast.Constant) and isinstance(n.value, str) else None


def main():
    src, build, gz, db_json, comm_json, inc_detail, out = sys.argv[1:8]
    files = sorted(p.decode() for p in open(gz, 'rb').read().split(b'\0') if p)
    pkgs = {}
    for f in files:
        if f.endswith('package.xml'):
            t = open(os.path.join(src, f), encoding='utf-8').read()
            name = re.search(r'<name>\s*([^<\s]+)\s*</name>', t).group(1)
            bt = re.search(r'<build_type>\s*([^<\s]+)\s*</build_type>', t)
            deps = re.findall(r'<(?:depend|exec_depend|build_depend|test_depend|build_export_depend)>\s*([^<\s]+)\s*<', t)
            pkgs[name] = {'dir': os.path.dirname(f), 'build_type': bt.group(1) if bt else None, 'deps': sorted(set(deps))}
    pkg_dirs = sorted(((v['dir'], k) for k, v in pkgs.items()), key=lambda x: len(x[0]), reverse=True)

    def pkg_of(p):
        for d, k in pkg_dirs:
            if p.startswith(d + '/'):
                return k
        return None
    # component registrations in the workspace
    reg = collections.defaultdict(list)
    reg_sites = []
    for f in files:
        if f.endswith(('.cpp', '.hpp', '.h')):
            t = open(os.path.join(src, f), encoding='utf-8', errors='replace').read()
            for m in re.finditer(r'^[ \t]*RCLCPP_COMPONENTS_REGISTER_NODE\s*\(\s*([\w:]+)\s*\)', t, re.M):
                reg[m.group(1).lstrip(':')].append(f)
                reg_sites.append((f, t.count('\n', 0, m.start()) + 1, m.group(1)))
    # generated mains
    gen_main = {}
    for pkg in os.listdir(build):
        d = os.path.join(build, pkg, 'rclcpp_components')
        if os.path.isdir(d):
            for fn in os.listdir(d):
                if fn.startswith('node_main_') and fn.endswith('.cpp'):
                    t = open(os.path.join(d, fn)).read()
                    cls = re.search(r'class_name\s*=\s*"rclcpp_components::NodeFactoryTemplate<\s*([\w:]+)\s*>"', t)
                    lib = re.search(r'library_name\s*=\s*"([^"]+)"', t)
                    gen_main[(pkg, fn[len('node_main_'):-4])] = {'class': cls.group(1) if cls else None, 'lib': lib.group(1) if lib else None}
    # target sources from the compile database outputs
    db = json.load(open(db_json))
    tsrc = collections.defaultdict(set)
    for pkgname in os.listdir(build):
        p = os.path.join(build, pkgname, 'compile_commands.json')
        if not os.path.exists(p):
            continue
        for e in json.load(open(p)):
            o = e.get('output') or re.search(r'-o\s+(\S+)', e.get('command', '')).group(1)
            m = re.match(r'CMakeFiles/([^/]+)\.dir/', o)
            f = os.path.normpath(os.path.join(e['directory'], e['file']))
            if m and f.startswith(src + '/'):
                tsrc[(pkgname, m.group(1))].add(os.path.relpath(f, src))
    # entry points
    eps = {}
    ep_sites = []
    for name, v in pkgs.items():
        sp = os.path.join(src, v['dir'], 'setup.py')
        if v['build_type'] == 'ament_python' and os.path.exists(sp):
            t = open(sp).read()
            for m in re.finditer(r"['\"]\s*([\w.-]+)\s*=\s*([\w.]+)\s*:\s*(\w+)\s*['\"]", t):
                exe, mod = m.group(1), m.group(2)
                cand = os.path.normpath(os.path.join(v['dir'], *mod.split('.'))) + '.py'
                eps[(name, exe)] = cand if cand in files else None
                ep_sites.append((os.path.join(v['dir'], 'setup.py'), t.count('\n', 0, m.start()) + 1, exe, mod, eps[(name, exe)]))

    def resolve(pkg, exe=None, plugin=None):
        if pkg not in pkgs:
            return 'external package', []
        if plugin:
            return 'component plugin class', sorted(set(reg.get(plugin.lstrip(':'), [])))
        if (pkg, exe) in eps:
            return 'ament_python console_scripts', [eps[(pkg, exe)]] if eps[(pkg, exe)] else []
        for (bp, e), g in gen_main.items():
            if e == exe and bp == pkg:
                return 'generated component main', sorted(set(reg.get((g['class'] or '').lstrip(':'), [])))
        for (bp, t), s in tsrc.items():
            if t == exe and bp == pkg:
                return 'CMake executable target sources', sorted(s)
        return 'not found', []
    # launch files
    lfiles = [f for f in files if ('/launch/' in '/' + f and f.endswith(('.py', '.xml', '.yaml')))]
    lfiles += [f for f in files if re.search(r'/test/test_[^/]*\.py$', f) and 'launch_ros' in open(os.path.join(src, f)).read()]
    actions = []
    for lf in lfiles:
        t = open(os.path.join(src, lf), encoding='utf-8').read()
        fmt = lf.rsplit('.', 1)[1]
        if fmt == 'py':
            for node in ast.walk(ast.parse(t)):
                if isinstance(node, ast.Call):
                    fn = node.func.attr if isinstance(node.func, ast.Attribute) else node.func.id if isinstance(node.func, ast.Name) else None
                    if fn in NODE_CALLS:
                        kw = {k.arg: k.value for k in node.keywords if k.arg}
                        actions.append({'file': lf, 'line': node.lineno, 'fmt': fmt, 'action': fn,
                                        'package': const(kw.get('package')) if 'package' in kw else None,
                                        'executable': const(kw.get('executable')) if 'executable' in kw else None,
                                        'plugin': const(kw.get('plugin')) if 'plugin' in kw else None,
                                        'nonliteral': [k for k in ('package', 'executable', 'plugin') if k in kw and const(kw[k]) is None],
                                        'remappings': 'remappings' in kw, 'parameters': 'parameters' in kw})
        elif fmt == 'xml':
            for m in re.finditer(r'<(node|executable|include|composable_node|node_container|let|arg)\b([^>]*)>', t):
                a = dict(re.findall(r'(\w+)="([^"]*)"', m.group(2)))
                actions.append({'file': lf, 'line': t.count('\n', 0, m.start()) + 1, 'fmt': fmt, 'action': m.group(1),
                                'package': a.get('pkg'), 'executable': a.get('exec'), 'plugin': a.get('plugin'),
                                'nonliteral': [k for k, v in a.items() if '$(' in v and k in ('pkg', 'exec', 'plugin')],
                                'remappings': False, 'parameters': False})
        else:
            lines = t.split('\n')
            for i, l in enumerate(lines):
                m = re.match(r'^\s*-\s*(node|executable|include|let|arg)\s*:', l)
                if m:
                    a = {}
                    for l2 in lines[i + 1:i + 12]:
                        mm = re.match(r'^\s+(\w+)\s*:\s*["\']?([^"\']*)["\']?\s*$', l2)
                        if re.match(r'^\s*-\s*\w+\s*:', l2):
                            break
                        if mm:
                            a.setdefault(mm.group(1), mm.group(2))
                    actions.append({'file': lf, 'line': i + 1, 'fmt': fmt, 'action': m.group(1), 'package': a.get('pkg'),
                                    'executable': a.get('exec'), 'plugin': None,
                                    'nonliteral': [k for k, v in a.items() if '$(' in v and k in ('pkg', 'exec')],
                                    'remappings': False, 'parameters': False})
    node_like = [a for a in actions if a['action'] in ('Node', 'LifecycleNode', 'ComposableNode', 'node', 'composable_node')]
    for a in node_like:
        how, tg = resolve(a['package'], a['executable'], a['plugin'] if a['action'] in ('ComposableNode', 'composable_node') else None)
        a['how'], a['targets'] = how, tg
    # light graph
    det = json.load(open(inc_detail))
    E = set((e[0], e[3]) for e in det['edges'])
    resolved = [a for a in node_like if a['targets']]
    lt_pairs = set((a['file'], t) for a in resolved for t in a['targets'])
    comm = json.load(open(comm_json))
    cpairs = set(tuple(p) for p in comm['file_pairs'])
    by_launch = collections.defaultdict(set)
    for a in resolved:
        for t in a['targets']:
            by_launch[a['file']].add(t)
    confirmed = set()
    for lf, ts in by_launch.items():
        for x in ts:
            for y in ts:
                if x < y and (x, y) in cpairs:
                    confirmed.add((x, y, lf))
    confirmed_pairs = set((x, y) for x, y, _ in confirmed)
    res = {
        'packages': len(pkgs), 'build_types': dict(collections.Counter(v['build_type'] for v in pkgs.values())),
        'launch_files': len(lfiles), 'launch_files_list': lfiles,
        'actions': len(actions), 'actions_by_fmt': dict(collections.Counter(a['fmt'] for a in actions)),
        'actions_by_kind': dict(collections.Counter(a['action'] for a in actions)),
        'node_like': len(node_like), 'node_like_nonliteral': [a for a in node_like if a['nonliteral']],
        'node_like_by_how': dict(collections.Counter(a['how'] for a in node_like)),
        'node_like_resolved_to_file': len(resolved),
        'node_like_not_resolved': [(a['file'], a['line'], a['package'], a['executable'], a['how']) for a in node_like if not a['targets']],
        'launch_target_file_pairs': len(lt_pairs),
        'launch_target_pairs_with_light_edge': sum(1 for p in lt_pairs if p in E or p[::-1] in E),
        'launch_actions_resolved_same_package': sum(1 for a in resolved if pkg_of(a['file']) == a['package']),
        'launch_with_remappings': [(a['file'], a['line']) for a in actions if a['remappings']],
        'launch_confirmed_comm_pairs': len(confirmed_pairs), 'launch_confirmed_list': sorted(confirmed),
        'entry_points': len(ep_sites), 'entry_points_resolved': sum(1 for e in ep_sites if e[4]),
        'entry_point_pairs_with_light_edge': sum(1 for e in ep_sites if e[4] and ((e[0], e[4]) in E or (e[4], e[0]) in E)),
        'component_register_sites': len(reg_sites), 'component_register_files': len(set(r[0] for r in reg_sites)),
        'component_files_with_incoming_edge': sum(1 for f in set(r[0] for r in reg_sites) if any(b == f for _, b in E)),
        'generated_mains': len(gen_main),
        'generated_mains_class_found': sum(1 for g in gen_main.values() if g['class'] and reg.get(g['class'].lstrip(':'))),
        'declared_ws_package_deps': sorted((k, d) for k, v in pkgs.items() for d in v['deps'] if d in pkgs and d != k),
    }
    det_pairs = res['declared_ws_package_deps']
    res['declared_ws_package_deps_with_light_edge'] = sum(1 for a, b in det_pairs if any(pkg_of(x) == a and pkg_of(y) == b or pkg_of(x) == b and pkg_of(y) == a for x, y in E))
    json.dump({'res': res, 'actions': actions, 'reg_sites': reg_sites, 'ep_sites': ep_sites, 'gen_main': {'%s/%s' % k: v for k, v in gen_main.items()}},
              open(out, 'w'), indent=1, default=list)
    for k, v in res.items():
        s = json.dumps(v, ensure_ascii=False, default=list)
        print(k, s if len(s) < 2500 else s[:2500] + ' ...')


if __name__ == '__main__':
    main()
